"""Structures: generated by the scenario, struck, repaired, worth their health, mirrored in DCS."""

import pytest

from dynacamp import scenario
from dynacamp.adapters.base import BuildingDestroyed, GameConnected, ShowStructure
from dynacamp.adapters.dcs.protocol import DcsTranslator, parse_static_name, static_name
from dynacamp.adapters.fake import FakeGame
from dynacamp.air import TargetKind, Task
from dynacamp.engine import Engine
from dynacamp.geo import Vec2
from dynacamp.scenario import ScenarioError
from dynacamp.structures import StructureKind
from dynacamp.systems import ato, structures

from .conftest import line_data, line_scenario


def test_depots_get_a_structure_and_scenarios_add_command_posts():
    data = line_data()
    data["structures"] = [{"id": "hq", "kind": "command", "province": "b", "name": "Blue HQ"}]
    state = scenario.from_dict(data)
    assert {"dep_a", "dep_e", "hq"} <= set(state.structures)
    assert state.structures["dep_e"].owner(state) == "red" and state.structures["hq"].kind is StructureKind.COMMAND
    data["structures"] = [{"id": "x", "kind": "bunker", "province": "b"}]
    with pytest.raises(ScenarioError, match="kind"):
        scenario.from_dict(data)


def test_a_strike_destroys_buildings_burns_stock_and_they_are_rebuilt():
    state = line_scenario()
    s = state.structures["dep_e"]
    depot = state.theater.provinces["e"].depot
    stock = depot.stock
    state.rng.seed(1)
    destroyed = structures.strike(state, s, eff=10.0, by="Viper 1")
    assert destroyed > 0 and s.health == pytest.approx(1 - destroyed / s.type.elements)
    assert depot.stock < stock
    state.time += s.type.repair_h * 3600 + 1
    structures.run(state, 1.0)
    assert s.health == 1.0


def test_health_scales_production_turnaround_and_planning():
    state = line_scenario()
    s = state.structures["dep_e"]
    s.destroyed = {i: 1e9 for i in range(s.type.elements // 2)}
    assert structures.depot_factor(state, "e") == pytest.approx(0.5)
    data = line_data()
    data["structures"] = [{"id": "hq", "kind": "command", "province": "e"}]
    state = scenario.from_dict(data)
    assert structures.packages_per_cycle(state, "red", 3) == 3
    state.structures["hq"].destroyed = {0: 1e9, 1: 1e9}
    assert structures.packages_per_cycle(state, "red", 3) == 1
    state.structures["hq"].destroyed[2] = 1e9
    assert structures.packages_per_cycle(state, "red", 3) == 0


def test_the_ato_plans_strikes_on_enemy_structures():
    state = line_scenario()
    found = [r for r in ato.requests(state, state.factions["blue"]) if r.task is Task.STRIKE]
    assert found and all(r.target_kind is TargetKind.STRUCTURE for r in found)
    assert "dep_e" in {r.target_id for r in found} and "dep_a" not in {r.target_id for r in found}


def test_static_names_round_trip():
    assert parse_static_name(static_name("dep_e", 3)) == ("dep_e", 3)
    assert parse_static_name("DC.b1.mbt.0") is None


def test_the_translator_places_only_what_changed_and_rebuilds_on_capture():
    tr = DcsTranslator()
    show = lambda army, idx: ShowStructure("dep_e", "depot", "RED", army, tuple((i, Vec2(i * 60.0, 0)) for i in idx))  # noqa: E731
    msg = tr.encode(show("russia", [0, 1, 2]))
    assert [s["data"]["name"] for s in msg["add"]] == [static_name("dep_e", i) for i in (0, 1, 2)] and not msg["remove"]
    assert msg["add"][0]["country"] == {"enum": "country.id.RUSSIA"}
    msg = tr.encode(show("russia", [0, 2]))
    assert not msg["add"] and msg["remove"] == [static_name("dep_e", 1)]
    msg = tr.encode(show("us", [0, 2]))  # captured: new country
    assert len(msg["add"]) == 2 and len(msg["remove"]) == 2 and msg["add"][0]["country"] == {"enum": "country.id.USA"}
    assert tr.decode({"msg": "static_dead", "name": static_name("dep_e", 2)}) == [BuildingDestroyed("dep_e", 2)]
    assert tr.decode({"msg": "hello", "theatre": "Caucasus"}) == [GameConnected("Caucasus")] and not tr.statics


def test_the_engine_shows_structures_and_takes_the_game_losses():
    state = line_scenario()
    game = FakeGame()
    engine = Engine(state, game)
    engine.step(1)
    shown = {c.structure_id: c for c in game.received if isinstance(c, ShowStructure)}
    assert set(shown) == set(state.structures)
    game.received.clear()
    engine.step(1)
    assert not [c for c in game.received if isinstance(c, ShowStructure)]  # unchanged: nothing resent
    game._reports.append(BuildingDestroyed("dep_e", 0))
    engine.step(1)
    s = state.structures["dep_e"]
    assert 0 in s.destroyed
    again = [c for c in game.received if isinstance(c, ShowStructure) and c.structure_id == "dep_e"]
    assert again and 0 not in {i for i, _ in again[-1].buildings}
    game._reports.append(GameConnected())
    game.received.clear()
    engine.step(1)
    assert len([c for c in game.received if isinstance(c, ShowStructure)]) == len(state.structures)
